-- V5.1 — Analisar Terreno
-- Incremental. Não elimina dados existentes.
begin;

create table if not exists public.land_analysis_rules(
  id bigint generated by default as identity primary key,
  rule_type text not null check(rule_type in ('checklist','alert','next_step')),
  category text not null,
  severity text not null default 'info' check(severity in ('info','baixo','medio','alto')),
  title text not null,
  message text not null,
  next_step text,
  conditions jsonb not null default '{}'::jsonb,
  position int not null default 100,
  verified_at date not null default date '2026-08-18',
  source_url text,
  status text not null default 'published'
);

create table if not exists public.land_analyses(
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  municipality text,
  article text,
  objective text not null,
  answers jsonb not null default '{}'::jsonb,
  risk_level text,
  checklist jsonb not null default '[]'::jsonb,
  alerts jsonb not null default '[]'::jsonb,
  next_steps jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now()
);

alter table public.land_analysis_rules enable row level security;
alter table public.land_analyses enable row level security;

drop policy if exists "published land rules readable" on public.land_analysis_rules;
create policy "published land rules readable" on public.land_analysis_rules
for select using(status='published' or public.is_admin());

drop policy if exists "admins manage land rules" on public.land_analysis_rules;
create policy "admins manage land rules" on public.land_analysis_rules
for all using(public.is_admin()) with check(public.is_admin());

drop policy if exists "users own land analyses read" on public.land_analyses;
create policy "users own land analyses read" on public.land_analyses
for select using(auth.uid()=user_id or public.is_admin());

drop policy if exists "users create own land analyses" on public.land_analyses;
create policy "users create own land analyses" on public.land_analyses
for insert with check(auth.uid()=user_id);

drop policy if exists "users delete own land analyses" on public.land_analyses;
create policy "users delete own land analyses" on public.land_analyses
for delete using(auth.uid()=user_id or public.is_admin());

delete from public.land_analysis_rules;

insert into public.land_analysis_rules(rule_type,category,severity,title,message,next_step,conditions,position,source_url) values
('checklist','identificacao','info','Confirmar identificação do prédio','Cruzar artigo matricial, descrição predial, localização/cartografia e área antes de interpretar o planeamento.',null,'{}',10,'https://www.dgterritorio.gov.pt/atividades/ordenamento/snit'),
('checklist','planeamento','info','Consultar PDM e instrumentos em vigor','Localizar o prédio no instrumento territorial aplicável e ler planta e regulamento em conjunto.',null,'{}',20,'https://www.dgterritorio.gov.pt/atividades/ordenamento/snit'),
('checklist','condicionantes','info','Consultar planta de condicionantes','Verificar REN, RAN, domínio hídrico, património, vias, infraestruturas e outras servidões/restrições aplicáveis.',null,'{}',30,'https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/2015-105297982'),
('checklist','acesso','info','Confirmar acesso jurídico e físico','Validar frente para via, servidões, capacidade de acesso e eventuais obras necessárias.',null,'{}',40,'https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875'),
